      depth: getDepth(),
      entitiesAlive: world.alive.size,
      player: player
        ? {
            id: player.id,
            pos: player.pos,
            hp: Number(vit?.hp || 0),
            maxHp: maxHpEffective,
          }
        : null,
    };
  }

