    world,
    dispatch,
    tick(turns = 1) {
      const n = Math.max(0, coerceInt(turns, 1));
      if (n > 0) world.tick(n);
    },
    view() {
      return buildWorldView(world);
    },
    observe(opts = {}) {
      return buildAgentObservation(world, opts);
    },
    snapshot,
    getPlayer() {
      return playerEntity(world);
    },
  };
}

