    tombstoneRepo: null,
  });

  world.step = PHASE_TURNS.sleep + PHASE_TURNS.breakfast;

  const pe = ensurePlayerSpawned(world, {
    x: spawnPos.x,
    y: spawnPos.y,
    classDef,
    playerName,
  });
  applyPlayerClassLoadout(world, pe.id, classDef);

